record.field:
.contract-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 40px;
    font-family: 'Georgia', 'Times New Roman', serif;
    line-height: 1.8;
    color: #333;
}

.contract-header {
    text-align: center;
    margin-bottom: 40px;
    border-bottom: 3px solid #0056b3;
    padding-bottom: 20px;
}

.contract-header h1 {
    font-size: 28px;
    margin: 0;
    color: #0056b3;
    text-transform: uppercase;
    letter-spacing: 2px;
}

.contract-header h2 {
    font-size: 18px;
    margin: 10px 0 0 0;
    color: #666;
    font-weight: normal;
}

.contract-section {
    margin-bottom: 30px;
}

.contract-section h3 {
    font-size: 16px;
    color: #0056b3;
    text-transform: uppercase;
    border-bottom: 1px solid #ddd;
    padding-bottom: 5px;
    margin-bottom: 15px;
}

.contract-section h4 {
    font-size: 14px;
    color: #333;
    margin: 15px 0 10px 0;
}

.contract-section p {
    margin: 10px 0;
    text-align: justify;
}

.contract-section ul {
    margin: 10px 0 10px 30px;
}

.contract-section li {
    margin: 5px 0;
}

.contract-table {
    width: 100%;
    border-collapse: collapse;
    margin: 15px 0;
}

.contract-table th,
.contract-table td {
    border: 1px solid #ddd;
    padding: 10px;
    text-align: left;
}

.contract-table th {
    background-color: #0056b3;
    color: white;
    font-weight: bold;
}

.contract-table tr:nth-child(even) {
    background-color: #f9f9f9;
}

.highlight {
    color: #0056b3;
    font-weight: bold;
    font-size: 18px;
}

.contract-footer {
    margin-top: 50px;
    border-top: 2px solid #0056b3;
    padding-top: 30px;
}

/* Legacy signature block styles (for backward compatibility) */
.signature-block {
    display: flex;
    justify-content: space-between;
    margin-top: 40px;
}

.signature-left,
.signature-right {
    width: 45%;
}

.signature-left p,
.signature-right p {
    margin: 5px 0;
}

/* New configurable signature zones styles */
.signature-zones {
    display: flex;
    justify-content: space-between;
    margin-top: 40px;
    page-break-inside: avoid;
}

.signature-zone {
    width: 45%;
    text-align: center;
}

.signature-zone p {
    margin: 5px 0;
}

.signature-box {
    border: 1px solid #ccc;
    min-height: 100px;
    margin: 10px 0;
    padding: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #fafafa;
}

.signature-box img {
    max-width: 200px;
    max-height: 80px;
}

@media print {
    .contract-container {
        padding: 20px;
    }

    .contract-section {
        page-break-inside: avoid;
    }
}
